const input = $input.first().json;

const clean = (value) => {
  const text = String(value == null ? '' : value).trim();
  if (!text || text === 'undefined' || text === 'null') return '';
  return text;
};

const description = clean(input.query || input.description);
const tileSize = clean(input.tileSize);
const site = clean(input.site).toLowerCase().replace(/^www\./, '');

if (!description) {
  return [{ json: { skip: true, reason: 'empty', options: [], description, tileSize, site } }];
}

const key = ('tile_' + [description, tileSize, site].join(' '))
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim()
  .split(' ')
  .filter(Boolean)
  .sort()
  .join('-')
  .slice(0, 180);

return [{ json: { cacheKey: key, description, tileSize, site, skip: false } }];

const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
const key = $('Build Cache Key').first().json;
const doc = $input.first().json || {};

if (key.skip) {
  return [{ json: { ...key, fresh: true, cached: [] } }];
}

const fetchedAt = Number(doc.fetchedAt);
const options = Array.isArray(doc.options) ? doc.options : null;
const fresh = Boolean(options && options.length && Number.isFinite(fetchedAt) && Date.now() - fetchedAt < SEVEN_DAYS);

return [{
  json: {
    ...key,
    fresh,
    cached: fresh ? options : [],
  },
}];

const key = $('Build Cache Key').first().json;
const response = $input.first().json || {};

const unwrap = (value) => {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const cleaned = value.replace(/```json|```/g, '').trim();
  if (!cleaned) return null;
  try { return JSON.parse(cleaned); } catch (error) { return null; }
};

const candidates = [
  response.output,
  response.products ? response : null,
  response.message?.content,
  response.choices?.[0]?.message?.content,
  response.content,
  response.text,
  response.response,
  response.data,
];

let products = [];
for (const candidate of candidates) {
  const parsed = unwrap(candidate);
  if (parsed && Array.isArray(parsed.products)) { products = parsed.products; break; }
  if (Array.isArray(parsed)) { products = parsed; break; }
}

const citations = [
  ...(Array.isArray(response.citations) ? response.citations : []),
  ...(Array.isArray(response.search_results) ? response.search_results.map((r) => r.url) : []),
].filter(Boolean);

const num = (value) => {
  const parsed = Number(String(value == null ? '' : value).replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const toPerSqm = (product) => {
  const price = num(product.price);
  if (price === null) return null;
  const unit = String(product.priceUnit || 'sqm').toLowerCase();
  if (unit === 'sqm') return price;
  if (unit === 'box') {
    const coverage = num(product.boxCoverageSqm);
    return coverage === null ? null : Math.round((price / coverage) * 100) / 100;
  }
  return null;
};

const PLAUSIBLE_MIN = 15;
const PLAUSIBLE_MAX = 250;

const options = products
  .map((product) => {
    const pricePerSqm = toPerSqm(product);
    if (pricePerSqm === null || pricePerSqm < PLAUSIBLE_MIN || pricePerSqm > PLAUSIBLE_MAX) return null;
    const url = String(product.url || '').trim();
    return {
      tileName: String(product.name || '').trim().slice(0, 120),
      sizeMm: String(product.sizeMm || product.size || '').trim(),
      finish: String(product.finish || '').trim(),
      pricePerSqm,
      retailer: String(product.retailer || '').trim(),
      sourceUrl: /^https?:\/\//i.test(url) ? url : (citations[0] || null),
      confidence: 'extracted',
    };
  })
  .filter((option) => option && option.tileName && option.sourceUrl)
  .slice(0, 3);

return [{
  json: {
    cacheKey: key.cacheKey,
    found: options.length > 0,
    options,
    fetchedAt: Date.now(),
    empty: options.length === 0,
  },
}];

const normalized = $('Normalize Tiles').first().json;

if (!normalized.options.length) {
  return [{ json: {
    found: false,
    message: 'No matching tile listing found. Use a category estimate instead and tell the customer the tile price is approximate.',
    options: [],
  } }];
}

return [{ json: {
  found: true,
  options: normalized.options.map((option) => ({
    tileName: option.tileName,
    pricePerSqm: option.pricePerSqm,
    retailer: option.retailer,
    sourceUrl: option.sourceUrl,
  })),
} }];
